(()=>{
  const es=(document.documentElement.lang||'en').toLowerCase().startsWith('es');
  const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const fmt=d=>{if(!d)return es?'No ingresada':'Not entered';try{return new Intl.DateTimeFormat(es?'es-US':'en-US',{dateStyle:'medium'}).format(new Date(d+'T12:00:00'))}catch{return d}};
  const downloadJson=(obj,name)=>{const blob=new Blob([JSON.stringify(obj,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();URL.revokeObjectURL(url)};
  const copyJson=async obj=>navigator.clipboard.writeText(JSON.stringify(obj,null,2));

  const chrono=document.querySelector('[data-r33-chronology-form]');
  if(chrono){
    const list=document.querySelector('[data-r33-event-list]'),out=document.querySelector('[data-r33-chronology-output]'),status=document.querySelector('[data-r33-chronology-status]');
    const add=document.querySelector('[data-r33-event-add]'),build=document.querySelector('[data-r33-chronology-build]'),copy=document.querySelector('[data-r33-chronology-copy]'),download=document.querySelector('[data-r33-chronology-download]'),print=document.querySelector('[data-r33-chronology-print]');
    const kinds={
      notice:{en:'Notice, denial, bill or decision received',es:'Aviso, denegación, factura o decisión recibida'},
      event:{en:'Incident, visit, repair, inspection or hearing',es:'Incidente, visita, reparación, inspección o audiencia'},
      contact:{en:'Contact with agency, insurer, provider, business or professional',es:'Contacto con agencia, aseguradora, proveedor, negocio o profesional'},
      document:{en:'Document, photo, estimate, record or receipt created/received',es:'Documento, foto, presupuesto, registro o recibo creado/recibido'},
      payment:{en:'Payment, charge, reimbursement or expense',es:'Pago, cargo, reembolso o gasto'},
      deadline:{en:'Date or deadline shown by the source',es:'Fecha o plazo mostrado por la fuente'}
    };
    let events=[],packet=null;
    const renderEvents=()=>{list.replaceChildren();events.sort((a,b)=>a.date.localeCompare(b.date)).forEach((ev,i)=>{const row=document.createElement('div');row.className='r33-event';row.innerHTML=`<strong>${esc(fmt(ev.date))}</strong><span>${esc(kinds[ev.kind][es?'es':'en'])}</span><button class="button" type="button" data-remove="${i}">${esc(es?'Quitar':'Remove')}</button>`;list.append(row)});list.querySelectorAll('[data-remove]').forEach(b=>b.addEventListener('click',()=>{events.splice(Number(b.dataset.remove),1);renderEvents()}))};
    add.addEventListener('click',()=>{const date=chrono.elements.date.value,kind=chrono.elements.kind.value;if(!date||!kinds[kind]){status.textContent=es?'Elige una fecha y un tipo de evento.':'Choose a date and event type.';return}events.push({date,kind});chrono.elements.date.value='';status.textContent=es?'Evento agregado.':'Event added.';renderEvents()});
    const evidenceBy=[
      {en:'Original notices/decisions and envelopes or delivery records',es:'Avisos/decisiones originales y sobres o registros de entrega'},
      {en:'Photos, estimates, receipts, invoices, EOBs, repair or visit records when relevant',es:'Fotos, presupuestos, recibos, facturas, EOB y registros de reparación o visita cuando correspondan'},
      {en:'Proof of prior contacts or submissions kept privately',es:'Prueba de contactos o envíos anteriores guardada en privado'},
      {en:'Questions for the responsible source or professional',es:'Preguntas para la fuente o profesional responsable'}
    ];
    build.addEventListener('click',()=>{if(!events.length){status.textContent=es?'Agrega al menos un evento.':'Add at least one event.';out.innerHTML=`<p class="empty-state">${esc(es?'Agrega al menos un evento fechado.':'Add at least one dated event.')}</p>`;return}packet={schemaVersion:'franklin.chronology-evidence.device-only.v1',release:'FR-NAV1.8.0-CANDIDATE-R33',community:'FRANKLIN_TN',submissionStatus:'NOT_SENT',events:[...events].sort((a,b)=>a.date.localeCompare(b.date)),evidenceCategories:evidenceBy.map(x=>x[es?'es':'en']),privacy:{freeNarrativeCollected:false,documentUpload:false,identifiersRequested:false,networkSubmission:false},boundary:es?'Organiza hechos y evidencia; no determina qué prueba es legalmente suficiente ni calcula plazos.':'Organizes facts and evidence; it does not decide what evidence is legally sufficient or calculate deadlines.'};out.innerHTML=`<div class="eyebrow">${esc(es?'CRONOLOGÍA DE FRANKLIN':'FRANKLIN CHRONOLOGY')}</div><h3>${esc(es?'Eventos en orden':'Events in order')}</h3><ol>${packet.events.map(e=>`<li><strong>${esc(fmt(e.date))}</strong> — ${esc(kinds[e.kind][es?'es':'en'])}</li>`).join('')}</ol><h3>${esc(es?'Lista de evidencia para revisar':'Evidence categories to review')}</h3><ul>${packet.evidenceCategories.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><p class="r33-warning">${esc(es?'Confirma en la fuente original qué fecha, regla, formato o evidencia exige el proceso actual. Esta cronología no calcula plazos ni decide relevancia legal.':'Confirm at the original source what date, rule, format or evidence the current process requires. This chronology does not calculate deadlines or decide legal relevance.')}</p><p class="r33-privacy">${esc(es?'Privacidad: el paquete queda en este dispositivo. No escribas aquí nombres, números de caso, póliza, reclamo, paciente o cuenta.':'Privacy: this packet stays on this device. Do not enter names or case, policy, claim, patient or account numbers here.')}</p>`;copy.disabled=download.disabled=print.disabled=false;status.textContent=es?'Cronología creada.':'Chronology built.';out.focus();window.FranklinProductHealth?.record('chronology_packet_built')});
    copy.addEventListener('click',async()=>{if(!packet)return;try{await copyJson(packet);status.textContent=es?'Cronología copiada.':'Chronology copied.'}catch{status.textContent=es?'No se pudo copiar automáticamente.':'Automatic copy was unavailable.'}});download.addEventListener('click',()=>packet&&downloadJson(packet,es?'franklin-cronologia-evidencia.json':'franklin-chronology-evidence.json'));print.addEventListener('click',()=>packet&&window.print());
  }

  const appeal=document.querySelector('[data-r33-appeal-form]');
  if(appeal){
    const out=document.querySelector('[data-r33-appeal-output]'),routes=document.querySelector('[data-r33-appeal-routes]'),status=document.querySelector('[data-r33-appeal-status]'),copy=document.querySelector('[data-r33-appeal-copy]'),download=document.querySelector('[data-r33-appeal-download]'),print=document.querySelector('[data-r33-appeal-print]');let packet=null;
    const areas={benefits:{en:'Government benefits / eligibility / agency review',es:'Beneficios / elegibilidad / revisión de agencia',route:'/get-it-done/'},insurance:{en:'Insurance / coverage / claim review',es:'Seguro / cobertura / revisión de reclamo',route:'/prepare-connected/?needs=insurance'},health:{en:'Health billing / authorization / coverage review',es:'Facturación de salud / autorización / revisión de cobertura',route:'/health-help/'},legal:{en:'Legal / court / administrative notice review',es:'Revisión de aviso legal / judicial / administrativo',route:'/legal-help/'},home:{en:'Home / property / contractor / landlord review',es:'Revisión de vivienda / propiedad / contratista / arrendador',route:'/home-property-help/'},auto:{en:'Vehicle / repair / title / crash claim review',es:'Revisión de vehículo / reparación / título / reclamo de choque',route:'/auto-vehicle-help/'}};
    const stages={starting:{en:'I need to understand the review/appeal path',es:'Necesito entender la ruta de revisión/apelación'},gathering:{en:'I am gathering documents or questions',es:'Estoy reuniendo documentos o preguntas'},submitted:{en:'I already submitted something and need to track next steps',es:'Ya envié algo y necesito seguir los próximos pasos'},hearing:{en:'A meeting, hearing, review or appointment is scheduled',es:'Hay una reunión, audiencia, revisión o cita programada'}};
    const checklist={decision:{en:'Original decision, denial, notice or bill',es:'Decisión, denegación, aviso o factura original'},instructions:{en:'Instructions or rights section from the responsible source',es:'Instrucciones o sección de derechos de la fuente responsable'},prior:{en:'Prior submissions, contacts or acknowledgements',es:'Envíos, contactos o acuses anteriores'},records:{en:'Relevant records, receipts, EOBs, estimates, photos or reports kept privately',es:'Registros, recibos, EOB, presupuestos, fotos o informes relevantes guardados en privado'},timeline:{en:'A dated chronology of key events',es:'Una cronología fechada de eventos clave'},questions:{en:'Questions for the agency, plan, insurer, provider or professional',es:'Preguntas para la agencia, plan, aseguradora, proveedor o profesional'}};
    appeal.addEventListener('submit',e=>{e.preventDefault();const area=areas[appeal.elements.area.value],stage=stages[appeal.elements.stage.value];if(!area||!stage){status.textContent=es?'Elige el tipo de revisión y la etapa.':'Choose the review type and stage.';return}const selected=[...appeal.querySelectorAll('input[name="prep"]:checked')].map(x=>x.value).filter(x=>checklist[x]);packet={schemaVersion:'franklin.appeal-review-prep.device-only.v1',release:'FR-NAV1.8.0-CANDIDATE-R33',community:'FRANKLIN_TN',submissionStatus:'NOT_SENT',area:appeal.elements.area.value,stage:appeal.elements.stage.value,dateShown:appeal.elements.shown.value||null,deadlineShown:appeal.elements.deadline.value||null,preparedCategories:selected,startingRoute:area.route,privacy:{freeNarrativeCollected:false,documentUpload:false,identifiersRequested:false,networkSubmission:false},boundary:es?'No determina elegibilidad, cobertura, derechos legales, resultado ni plazo válido. Confirma el proceso actual en la fuente responsable.':'Does not determine eligibility, coverage, legal rights, outcome or a valid deadline. Confirm the current process at the responsible source.'};out.innerHTML=`<div class="eyebrow">${esc(es?'PREPARACIÓN PARA REVISIÓN':'REVIEW / APPEAL PREPARATION')}</div><h3>${esc(area[es?'es':'en'])}</h3><dl><dt><strong>${esc(es?'Etapa':'Stage')}</strong></dt><dd>${esc(stage[es?'es':'en'])}</dd><dt><strong>${esc(es?'Fecha mostrada':'Date shown')}</strong></dt><dd>${esc(fmt(packet.dateShown))}</dd><dt><strong>${esc(es?'Plazo mostrado':'Deadline shown')}</strong></dt><dd>${esc(fmt(packet.deadlineShown))}</dd></dl><h3>${esc(es?'Qué preparar':'What to prepare')}</h3><ul>${selected.length?selected.map(k=>`<li>${esc(checklist[k][es?'es':'en'])}</li>`).join(''):`<li>${esc(es?'Revisa la decisión original, las instrucciones de la fuente y una cronología de eventos.':'Review the original decision, the source instructions and a chronology of events.')}</li>`}</ul><h3>${esc(es?'Preguntas para confirmar':'Questions to confirm')}</h3><ul><li>${esc(es?'¿Qué proceso de revisión o apelación describe la fuente responsable actualmente?':'What review or appeal process does the responsible source currently describe?')}</li><li>${esc(es?'¿Qué fecha aparece y qué significa según esa fuente?':'What date is shown, and what does that source say the date means?')}</li><li>${esc(es?'¿Qué documentos, formato o canal de envío exige la fuente?':'What documents, format or submission channel does the source require?')}</li><li>${esc(es?'¿Necesito ayuda de un profesional antes de actuar?':'Do I need professional help before acting?')}</li></ul><p class="r33-warning">${esc(packet.boundary)}</p><p class="r33-privacy">${esc(es?'Privacidad: no pegues el aviso ni escribas identificadores sensibles en esta herramienta.':'Privacy: do not paste the notice or enter sensitive identifiers into this tool.')}</p>`;routes.replaceChildren();const a=document.createElement('a');a.href=area.route;a.innerHTML=`<strong>${esc(es?'Abrir punto de partida':'Open starting point')}</strong><br><span>${esc(area[es?'es':'en'])}</span>`;routes.append(a);copy.disabled=download.disabled=print.disabled=false;status.textContent=es?'Paquete creado.':'Preparation packet built.';out.focus();window.FranklinProductHealth?.record('appeal_review_packet_built')});
    appeal.addEventListener('reset',()=>setTimeout(()=>{packet=null;out.innerHTML=`<p class="empty-state">${esc(es?'Elige el tipo de revisión.':'Choose a review type.')}</p>`;routes.replaceChildren();copy.disabled=download.disabled=print.disabled=true;status.textContent=''},0));copy.addEventListener('click',async()=>{if(!packet)return;try{await copyJson(packet);status.textContent=es?'Paquete copiado.':'Packet copied.'}catch{status.textContent=es?'No se pudo copiar automáticamente.':'Automatic copy was unavailable.'}});download.addEventListener('click',()=>packet&&downloadJson(packet,es?'franklin-preparacion-revision.json':'franklin-appeal-review-prep.json'));print.addEventListener('click',()=>packet&&window.print());
  }
})();
